Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",

  "data": {
    "name": "dataset"
  },

  "width": "container",
  "height": "container",

  "transform": [
    {
      "calculate": "(random()-0.5)*0.6",
      "as": "jitter"
    }
  ],

  "layer": [

    {
      "mark": {
        "type": "point",
        "filled": true,
        "size": 90,
        "opacity": 0.20,
        "stroke": "white",
        "strokeWidth": 0.5
      },

      "encoding": {

        "x": {
          "field": "Nombre Corto",
          "type": "nominal",
          "sort": {
            "op": "median",
            "field": "nFlores",
            "order": "descending"
          }
        },

        "xOffset": {
          "field": "jitter"
        },

        "y": {
          "field": "nFlores",
          "type": "quantitative"
        },

        "color": {
          "field": "Fundo",
          "type": "nominal",
          "legend": null
        },

        "tooltip": [

          {
            "field": "Nombre Corto",
            "title": "Evaluador"
          },

          {
            "field": "Fecha",
            "title": "Fecha"
          },

          {
            "field": "Fundo",
            "title": "Fundo"
          },

          {
            "field": "Modulo",
            "title": "Módulo"
          },

          {
            "field": "Lote",
            "title": "Lote"
          },

          {
            "field": "nFlores",
            "title": "Flores"
          }

        ]
      }
    },

    {
      "mark": {
        "type": "boxplot",
        "extent": 1.5,
        "size": 70,
        "ticks": true,
        "median": {
          "color": "black",
          "strokeWidth": 3
        }
      },

      "encoding": {

        "x": {
          "field": "Nombre Corto",
          "type": "nominal",
          "sort": {
            "op": "median",
            "field": "nFlores",
            "order": "descending"
          },
          "axis": {
            "labelAngle": 0,
            "labelFontSize": 16,
            "labelLimit": 180,
            "title": "Evaluador",
            "titleFontSize": 18,
            "titleFontWeight": "bold"
          }
        },

        "y": {
          "field": "nFlores",
          "type": "quantitative",
          "title": "Flores por Planta",
          "axis": {
            "labelFontSize": 16,
            "titleFontSize": 18,
            "titleFontWeight": "bold",
            "grid": true
          }
        },

        "color": {
          "field": "Fundo",
          "type": "nominal",
          "legend": null
        }
      }
    }

  ],

  "config": {

    "view": {
      "stroke": null
    },

    "axis": {
      "domain": true,
      "domainWidth": 1.5,
      "tickWidth": 1.5,
      "tickSize": 6,
      "labelFont": "Segoe UI",
      "titleFont": "Segoe UI"
    }

  }
}'
